using System;
using System.Collections.Generic;
using System.Linq;
using WorkEnv;

class WorkflowTests {
 static int checks,failures;
 static void Test(bool ok,string name){checks++;if(!ok)failures++;Console.WriteLine((ok?"PASS ":"FAIL ")+name);}
 static Report Fixture(bool enabled,string expected){var list=Engine.CompareV4(new Probe("192.0.2.10",null),new Probe("192.0.2.10",null),enabled,expected);list.Add(new Item("ipv6-public","unknown","虚构","未验证","虚构", ""));list.Add(new Item("ext-rtc-compare","unknown","虚构","未验证","虚构", ""));list.Add(new Item("ext-dns-lookup","pass","虚构","解析成功","虚构", ""));int n=0;foreach(string key in new[]{"ext-ai-claude","ext-ai-openai","ext-ai-grok"})list.Add(Functional.HttpEvidence(key,"example.invalid","IPv4",1,2,3,4,new[]{421,403,503}[n++]));return Engine.Assemble(list);}
 static ScoreAssessment Score(Report r){return ScoreAssessment.Evaluate(r,false,DateTime.Now,DateTimeOffset.Now,new string[0]);}
 static int Main(){var r=Fixture(true,"192.0.2.10");var a=Score(r);Test(a.Score==100&&a.UnknownWeight==0&&a.Level=="green"&&a.Headline=="网络连接正常，可以开始办公"&&a.Action.Contains("登录")&&a.Action.Contains("模型"),"TLS 成功而 HTTP 421/403/503，IPv6/ICE 未验证：IPv4 连接得分 100，说明边界");Test(ScoreAssessment.HttpLabel(r.items.First(x=>x.key=="ext-ai-claude")).Contains("421"),"HTTP 状态单独呈现");r.items.RemoveAll(x=>x.key=="ext-ai-grok");a=Score(r);Test(a.Score==80&&a.UnknownWeight==20&&a.Action.Contains("Codex / OpenAI")&&a.Action.Contains("Grok"),"单个服务未知显示区间，不阻塞已验证服务");r=Fixture(true,"192.0.2.11");a=Score(r);Test(a.Score==95&&a.Level=="red"&&a.Headline.Contains("出口"),"固定 IPv4 不一致优先警告");r=Fixture(false,"");var cert=r.items.First(x=>x.key=="ext-ai-openai");cert.transportState="attention";cert.failureCode="certificate-invalid";a=Score(r);Test(a.Score==80&&a.Level=="red"&&a.Headline.Contains("证书"),"证书异常不算 TLS 成功");r=Fixture(true,"192.0.2.10");var v6=r.items.First(x=>x.key=="ipv6-public");v6.status="pass";v6.observation="2001:db8::10";a=Score(r);Test(a.Score==100&&a.Level=="yellow"&&a.Action.Contains("IPv6"),"额外公网 IPv6 单独提醒");r=Fixture(false,"");r.items.First(x=>x.key=="ext-ai-grok").transportState="unknown";a=Score(r);Test(a.Score==80&&a.UnknownWeight==20,"TLS 未完成不会计为通过");a=ScoreAssessment.Evaluate(r,false,DateTime.Now.AddSeconds(-31),DateTimeOffset.Now,new string[0]);Test(a.Points.First(x=>x.Id=="exit-consistency").Status=="unknown","过期基础证据不能当作当前通过");r=Fixture(false,"");r.items.RemoveAll(x=>x.key.StartsWith("ext-ai-"));a=Score(r);Test(a.Headline.Contains("暂未确认 AI")&&a.UnknownWeight==60,"所有服务未知不能说已连通");r=Fixture(false,"");r.items.Add(new Item("ext-ai-openai","unknown","虚构","取消","虚构",""){transportState="unknown"});a=Score(r);Test(a.Points.First(x=>x.Id=="ai-openai").Status=="unknown"&&a.Score==80,"同服务新鲜证据冲突不取首个通过");r=Fixture(false,"");r.items.First(x=>x.key=="ipv6-public").status="pass";r.items.Add(new Item("ipv6-path","pass","虚构","无路径","虚构",""){identity="ipv6-path-no-path"});a=Score(r);Test(a.Level=="yellow"&&a.Headline.Contains("冲突"),"公网 IPv6 与无路径冲突需要核对");r=Fixture(false,"");r.items.First(x=>x.key=="ext-rtc-compare").status="attention";a=Score(r);Test(a.Level=="red"&&a.Headline.Contains("不同出口"),"浏览器路径已确认冲突优先提示");r=Fixture(false,"");r.items.First(x=>x.key=="ext-ai-claude").observedAt=DateTimeOffset.Now.AddMinutes(1).ToString("o");a=Score(r);Test(a.UnknownWeight==20,"未来时间证据不通过");r=Fixture(false,"");r.items.Add(new Item("check","unknown","虚构","取消","虚构",""));a=Score(r);Test(a.Level=="yellow"&&a.Headline.Contains("核对"),"整轮取消不作完整网络结论");Console.WriteLine("TOTAL "+checks+" FAIL "+failures);return failures==0?0:1;}
}
